sys_transform_entry.source_script:
answer = (function transformEntry(source) {

    var company = JSON.parse(source.u_companydetails || '{}');
    var device = JSON.parse(source.u_devicedetails || '{}');

    // Only the lines that carry a value are written, so a sparse alert does not produce
    // a work note full of empty labels.
    var lines = [
        ['Company Name', company.companyName],
        ['Device Name', device.deviceName],
        ['Serial Number', device.serialNumber],
        ['Device Model', device.deviceModel],
        ['Alert Type', label(source.u_type)],
        ['Alert Subtype', label(source.u_subtype)],
        ['Alert Status', label(source.u_status)],
        ['Source Location', '' + source.u_sourcelocation],
        ['Alert Rule', '' + source.u_alertruleid],
        ['Occurred At', stamp(source.u_occuredat)]
    ];

    var out = [];
    for (var i = 0; i < lines.length; i++) {
        if (lines[i][1])
            out.push(lines[i][0] + ': ' + lines[i][1]);
    }
    return out.join('\n');

    /** type/subtype/status arrive as stringified {"name":...,"value":...} - show the label. */
    function label(field) {
        var raw = ('' + (field || '')).trim();
        if (!raw)
            return '';
        try {
            var parsed = JSON.parse(raw);
            return parsed.value || parsed.name || raw;
        } catch (e) {
            return raw;
        }
    }

    /**
     * WXP sends epoch milliseconds as a string.
     *
     * getValue(), not getDisplayValue(). GlideDateTime holds its value in UTC and
     * getDisplayValue() renders it in the *session user's* timezone - so the same alert
     * produced 01:24 when imported as incidentConnect and 23:24 as saurav.sarkar, and the
     * work note froze whichever one happened to run. The zone is labelled because an
     * unmarked timestamp cannot even be corrected for by a reader.
     */
    function stamp(millis) {
        var value = Number('' + (millis || ''));
        if (!value)
            return '';
        var when = new GlideDateTime();
        when.setNumericValue(value);
        return when.getValue() + ' UTC';
    }

})(source);
